const staticData = $getWorkflowStaticData('global');
if (staticData.lastId === undefined) staticData.lastId = 0;

const newItems = items.filter(item => item.json.id > staticData.lastId);

if (newItems.length > 0) {
  staticData.lastId = Math.max(...items.map(item => item.json.id));
}

return newItems;

